def merge_intervals(intervals):
    sorted_intervals = sorted((list(interval) for interval in intervals), key=lambda interval: (interval[0], interval[1]))
    merged = []
    for start, end in sorted_intervals:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

import heapq

def toposort(nodes, edges):
    adjacency = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}

    for source, destination in set(edges):
        adjacency[source].append(destination)
        indegree[destination] += 1

    available = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(available)

    order = []
    while available:
        node = heapq.heappop(available)
        order.append(node)
        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(available, neighbor)

    if len(order) != len(nodes):
        raise ValueError("cycle detected")

    return order

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    batches = []
    current = []
    total = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("invalid weight")
        if current and total + weight > limit:
            batches.append(current)
            current = []
            total = 0
        current.append(name)
        total += weight
    if current:
        batches.append(current)
    return batches

import re

def parse_env(text):
    result = {}
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid line: {line!r}")
        key, _, value = line.partition('=')
        key = key.strip()
        value = value.strip()
        if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', key):
            raise ValueError(f"Invalid key: {key!r}")
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]
        result[key] = value
    return result

def parse_sse(chunks):
    text = b"".join(chunks).decode("utf-8")
    events = []
    data_lines = []
    pos = 0
    n = len(text)

    while pos < n:
        idx_lf = text.find('\n', pos)
        idx_cr = text.find('\r', pos)

        if idx_lf == -1 and idx_cr == -1:
            line = text[pos:]
            pos = n
        else:
            if idx_lf == -1:
                idx = idx_cr
            elif idx_cr == -1:
                idx = idx_lf
            else:
                idx = min(idx_lf, idx_cr)
            line = text[pos:idx]
            ch = text[idx]
            pos = idx + 1
            if ch == '\r' and pos < n and text[pos] == '\n':
                pos += 1

        if line == '':
            if data_lines:
                data = "\n".join(data_lines)
                data_lines = []
                if data == "[DONE]":
                    return events
                events.append(data)
            continue

        if line.startswith(':'):
            continue

        if ':' in line:
            field, value = line.split(':', 1)
            if value.startswith(' '):
                value = value[1:]
        else:
            field, value = line, ''

        if field == 'data':
            data_lines.append(value)

    return events

import math

def retry_delay(attempt, base, cap):
    if isinstance(attempt, bool) or not isinstance(attempt, int):
        raise ValueError("attempt must be a nonnegative integer")
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    try:
        base = float(base)
        cap = float(cap)
    except Exception as e:
        raise ValueError("base and cap must be finite nonnegative numbers") from e
    if not math.isfinite(base) or base < 0.0:
        raise ValueError("base must be finite and nonnegative")
    if not math.isfinite(cap) or cap < 0.0:
        raise ValueError("cap must be finite and nonnegative")
    if base == 0.0 or cap == 0.0:
        return 0.0
    t = attempt * math.log(2.0)
    if not math.isfinite(t):
        return cap
    log_product = math.log(base) + t
    if log_product >= math.log(cap):
        return cap
    return math.exp(log_product)

def fifo_admit(active, queued, budget, slots):
    for r in queued:
        if r > budget:
            raise ValueError("queued reservation exceeds budget")
    admitted = []
    token_left = budget - sum(active)
    slot_left = slots - len(active)
    idx = 0
    for r in queued:
        if slot_left > 0 and token_left >= r:
            admitted.append(r)
            token_left -= r
            slot_left -= 1
            idx += 1
        else:
            break
    remaining = list(queued[idx:])
    return admitted, remaining
